Placebo: 1 tablet daily for 16 weeks","deathsNumAffected":0,"deathsNumAtRisk":14,"seriousNumAffected":0,"seriousNumAtRisk":14,"otherNumAffected":0,"otherNumAtRisk":14}]},"moreInfoModule":{"limitationsAndCaveats":{"description":"Limitations of our pilot study may include the relatively short 16-week Canagliflozin therapy, which may be inadequate to see significant changes in certain clinical and cellular parameters. This maybe also because of the small sample size. Further studies with a larger population and longer duration may be helpful to further define the mechanisms behind our findings."},"certainAgreement":{"piSponsorEmployee":false,"restrictiveAgreement":false},"pointOfContact":{"title":"Dr. Sabyasachi Sen","organization":"George Washington University Medical Faculty Associates","email":"ssen1@email.gwu.edu","phone":"202-741-2233"}}},"documentSection":{"largeDocumentModule":{"largeDocs":[{"typeAbbrev":"Prot_SAP","hasProtocol":true,"hasSap":true,"hasIcf":false,"label":"Study Protocol and Statistical Analysis Plan","date":"2017-12-15","uploadDate":"2022-08-16T11:15","filename":"Prot_SAP_000.pdf","size":700574}]}},"derivedSection":{"miscInfoModule":{"versionHolder":"2026-09-21"},"conditionBrowseModule":{"meshes":[{"id":"D003924","term":"Diabetes Mellitus, Type 2"},{"id":"D051437","term":"Renal Insufficiency"}],"ancestors":[{"id":"D003920","term":"Diabetes Mellitus"},{"id":"D044882","term":"Glucose Metabolism Disorders"},{"id":"D008659","term":"Metabolic Diseases"},{"id":"D009750","term":"Nutritional and Metabolic Diseases"},{"id":"D004700","term":"Endocrine System Diseases"},{"id":"D007674","term":"Kidney Diseases"},{"id":"D014570","term":"Urologic Diseases"},{"id":"D052776","term":"Female Urogenital Diseases"},{"id":"D005261","term":"Female Urogenital Diseases and Pregnancy Complications"},{"id":"D000091642","term":"Urogenital Diseases"},{"id":"D052801","term":"Male Urogenital Diseases"}]},"interventionBrowseModule":{"meshes":[{"id":"D000068896","term":"Canagli