{"protocolSection":{"identificationModule":{"nctId":"NCT06987708","orgStudyIdInfo":{"id":"Pro2024-0235"},"secondaryIdInfos":[{"id":"MGUS-SM-Lifestyle","type":"OTHER","domain":"HMH"}],"organization":{"fullName":"Hackensack Meridian Health","class":"OTHER"},"briefTitle":"Evaluating the Impact of a 12-month Multi-Modal Lifestyle Management Intervention on Disease Relevant Biomarkers","officialTitle":"Evaluating the Impact of a 12-month Multi-Modal Lifestyle Management Intervention on Disease Relevant Biomarkers Associated With Monoclonal Gammopathy of Unknown Significance (MGUS) and Smoldering Myeloma (SM): A Prospective Intervention Pilot Study"},"statusModule":{"statusVerifiedDate":"2026-08","overallStatus":"NOT_YET_RECRUITING","expandedAccessInfo":{"hasExpandedAccess":false},"startDateStruct":{"date":"2026-10-01","type":"ESTIMATED"},"primaryCompletionDateStruct":{"date":"2028-10-01","type":"ESTIMATED"},"completionDateStruct":{"date":"2028-10-01","type":"ESTIMATED"},"studyFirstSubmitDate":"2025-05-16","studyFirstSubmitQcDate":"2025-05-16","studyFirstPostDateStruct":{"date":"2025-05-23","type":"ACTUAL"},"lastUpdateSubmitDate":"2026-08-21","lastUpdatePostDateStruct":{"date":"2026-08-24","type":"ACTUAL"}},"sponsorCollaboratorsModule":{"responsibleParty":{"type":"SPONSOR"},"leadSponsor":{"name":"Hackensack Meridian Health","class":"OTHER"},"collaborators":[{"name":"Center for Cancer Lifestyle Management","class":"UNKNOWN"}]},"oversightModule":{"oversightHasDmc":true,"isFdaRegulatedDrug":false,"isFdaRegulatedDevice":false,"isUsExport":false},"descriptionModule":{"briefSummary":"A prospective, pilot study to assess the impact of a 12-month multi-focal lifestyle intervention on myeloma-relevant biomarkers in patients with MGUS or SM. The multimodal lifestyle intervention has six foci that patients will participate in over the course of one-year.","detailedDescription":"Patients with a diagnosis of MGUS or SM who are willing and able to participate in this 12-month multimodal lifestyle approach. Eligible patients include those 18 years of age and older diagnosed with MGUS/SM, ECOG PS 0-2, absence of significant comorbidities, and ability to speak/read/understand English.

The multimodal lifestyle intervention has six foci: Positive cognition \[mindset\], Exercise/movement, Stress Reduction, Social Connection, Emotional Wellbeing, and Nutrition. All programming will take place online to maximize convenience/sustained participation."},"conditionsModule":{"conditions":["Monoclonal Gammopathy of Uncertain Significance","Smoldering Myeloma"]},"designModule":{"studyType":"INTERVENTIONAL","phases":["NA"],"designInfo":{"allocation":"NA","interventionModel":"SINGLE_GROUP","primaryPurpose":"PREVENTION","maskingInfo":{"masking":"NONE"}},"enrollmentInfo":{"count":67,"type":"ESTIMATED"}},"armsInterventionsModule":{"armGroups":[{"label":"Multimodal Lifestyle Intervention","type":"EXPERIMENTAL","interventionNames":["Other: The Multimodal Lifestyle Intervention"]}],"interventions":[{"type":"OTHER","name":"The Multimodal Lifestyle Intervention","description":"The multimodal lifestyle intervention has six foci: positive cognition, exercise/movement, stress reduction, social connection, emotional well-being, and nutrition","armGroupLabels":["Multimodal Lifestyle Intervention"]}]},"outcomesModule":{"primaryOutcomes":[{"measure":"Efficacy of multi-modal lifestyle intervention based on any of the 3 specified myeloma tumor burden biomarker surrogates","description":"Efficacy of the multi-modal lifestyle intervention will be based on measurements of 3 myeloma-relevant biomarkers: M-Spike Protein, Free kappa light chains, and Free lambda-light chains. We will first determine which monoclonal protein is dominant for a given patient based on his/her/their individual lab values. These labs will be taken at baseline and compared to levels at 4-, 8-, and 12-month intervals to assess for changes in protein levels.","timeFrame":"At study entry, 4 months, 8 months, and up to 12 months"}],"secondaryOutcomes":[{"measure":"Patient Acceptability (engagement) of the Lifestyle Intervention","description":"Patient acceptability will be measured by a patient acceptability questionnaire","timeFrame":"At study entry, 4 months, 8 months, and up to 12 months"},{"measure":"Patient Adherence (compliance) to the Lifestyle Intervention","description":"Patient adherence will be measured based on attendance at clinic visits, the various scheduled individual and group meetings across all intervention components, and via the use of wearable technology","timeFrame":"At study entry, 4 months, 8 months, and up to 12 months"}],"otherOutcomes":[{"measure":"Correlation between specified inflammation biomarkers and any of the 3 specified myeloma tumor burden biomarker surrogates","description":"Inflammation will be measured using 3 surrogate markers: IL-6, TNF-alpha, and VEGF. These labs will be taken at baseline and compared to levels at 4-, 8-, and 12-month intervals to assess for a reduction in these levels and any observed correlation with myeloma markers","timeFrame":"At study entry, 4 months, 8 months, and up to 12 months"},{"measure":"Correlation between patient glucose levels/changes and any of the 3 specified myeloma tumor burden biomarker surrogates","description":"Fasting insulin levels and hemoglobin A1c (HbA1c) measurements will be taken at baseline and compared to levels at 4-, 8-, and 12-month intervals to assess for improvements and any observed correlation with designated myeloma markers. Average of In-Range Continuous Glucose Monitor (CGM) recordings will be calculated at baseline and compared to levels at 4-, 8-, and 12-month intervals to assess for improvements and correlation with select myeloma biomarkers.","timeFrame":"At study entry, 4 months, 8 months, and up to 12 months"},{"measure":"Correlation between lipid-related biomarkers/changes and any of the 3 specified myeloma tumor burden biomarker surrogates","description":"Body mass index (BMI), Abdominal Visceral Fat; High Density Lipoprotein - Cholesterol (HDL-C), Apolipoprotein A-1(APO A1), and Adiponectin will be measured at baseline and compared to levels at 4-, 8-, and 12-month intervals to assess for improvements and any correlation with the identified myeloma biomarkers","timeFrame":"At study entry, 4 months, 8 months, and up to 12 months"},{"measure":"Validation of the PESSEN questionnaire","description":"The PESSEN Questionnaire (Positive cognition, Emotional wellbeing, Social connection, Stress reduction, Exercise, Nutrition) is designed to assess a patient's overall lifestyle wellness as measured across six areas, assess the degree to which a patient believes that these six areas of lifestyle interventions can improve their cancer outcome, and to assign them a lifestyle wellness score.","timeFrame":"At study entry, 4 months, 8 months, and up to 12 months"}]},"eligibilityModule":{"eligibilityCriteria":"Inclusion Criteria:

* Adults 18 years or older.
* Diagnosed with MGUS or SM based on commonly accepted criteria per the

International Multiple Myeloma Working Group (IMWG), defined as follows:

a. For a diagnosis of Smoldering Multiple Myeloma (SM), both criteria must be met: i. Serum monoclonal protein (IgG or IgA) ≥ 30g/L or urinary monoclonal protein ≥ 500mg per 24h and/or clonal bone marrow plasma cells 10-60% ii. Absence of myeloma-defining events or amyloidosis b. For a diagnosis of Non-IgM Monoclonal Gammopathy of Undetermined

Significance (MGUS):

i. Serum monoclonal protein \<30g/L ii. Clonal bone marrow plasma cells \<10% iii. Absence of end-organ damage such as hypercalcemia, renal insufficiency, anemia, and bone lesions (CRAB) or amyloidosis that can be attributed to the plasma cell proliferative disorder c. For a diagnosis of IgM MGUS: i. Serum IgM monoclonal protein \<30g/L ii. No evidence of anemia, constitutional symptoms, hyperviscosity, lymphadenopathy, hepatosplenomegaly, or other end-organ damage that can be attributed to the plasma cell proliferative disorder d. For a diagnosis of light change MGUS: i. Abnormal FLC ratio (\<0.26 or \>1.65) ii. Increased level of the appropriate free light chain (increased κ FLC in patients with ratio \>1.65 and increased λ FLC in patients with ratio \<0.26) iii. No immunoglobulin heavy chain expression on immunofixation iv. Absence of end-organ damage such as hypercalcemia, renal insufficiency, anemia, and bone lesions (CRAB) or amyloidosis that can be attributed to the plasma cell proliferative disorder v. Clonal bone marrow plasma cells \<10% vi. Urinary monoclonal protein \<500mg/24h

* Eastern Cooperative Oncology Group (ECOG) performance status score of 0, 1 or 2
* Ability to speak, read and comprehend the English language.
* Absence of significant intercurrent illness such as uncontrolled heart failure, unstable angina, cardiac arrhythmia and psychiatric illness which would preclude informed consent.
* Patient understands the purpose of the trial and procedures required for the trial, and can provide signed informed consent as which includes compliances with the requirements and restrictions listed in the informed consent form (ICF) and in the study protocol.
* Ability to adhere to the study visit schedule and all the protocol requirements, including surveillance imaging and test specimen (blood sample) collection at specified time points.

Exclusion Criteria:

* Evidence of any one or more of the following biomarkers of malignancy, or myeloma-defining events (MDEs) meeting IMWG criteria for a diagnosis of multiple myeloma:

  1. 60% or greater clonal plasma cells on bone marrow examination
  2. Serum involved / uninvolved free light chain ratio of 100 or greater, provided the absolute level of the involved light chain is at least 100mg/L (a patient's involved free light chain either kappa or lambda is the one that is above the normal reference range; the uninvolved free light chain is the one that is typically in, or below, the normal range)
  3. More than one focal lesion on MRI that is at least 5mm or greater in size.
* Evidence of end-organ damage as per the IMWG CRAB criteria, defined as follows:

  1. Hypercalcemia: serum calcium \>0.25 mmol/L (\>1mg/dL) higher than the upper limit of normal or \>2.75 mmol/L (\>11mg/dL)
  2. Renal insufficiency: creatinine clearance \<40 mL per minute or serum creatinine \>177mol/L (\>2mg/dL)
  3. Anemia: hemoglobin value of \>20g/L below the lowest limit of normal, or a hemoglobin value \<100g/L
  4. Bone lesions: one or more osteolytic lesions on skeletal radiography, CT, or PET/CT. If bone marrow has \<10% clonal plasma cells, more than one bone lesion is required to distinguish from solitary plasmacytoma with minimal marrow involvement
* Unwillingness or inability to follow required intervention behaviors, including any safety issues related to participating in any part of the intervention (e.g., a contraindication to gentle movement/exercise, BMI \<18 kg/m2, etc.).
* Pregnancy or breastfeeding
* Patient has any condition for which, in the opinion of the investigator, participation would not be in the best interest of the patient (e.g., compromise the well-being) or that could prevent, limit, or confound the protocol-specified assessments.","healthyVolunteers":false,"sex":"ALL","minimumAge":"18 Years","stdAges":["ADULT","OLDER_ADULT"]},"contactsLocationsModule":{"centralContacts":[{"name":"Oncology Clinical Research Referral Office","role":"CONTACT","phone":"551-996-1777","email":"OncologyResearchReferral@hmhn.org"}],"overallOfficials":[{"name":"David Siegel, MD","affiliation":"Hackensack Meridian Health","role":"PRINCIPAL_INVESTIGATOR"}]},"referencesModule":{"references":[{"pmid":"27696254","type":"BACKGROUND","citation":"Mateos MV, Landgren O. MGUS and Smoldering Multiple Myeloma: Diagnosis and Epidemiology. Cancer Treat Res. 2016;169:3-12. doi: 10.1007/978-3-319-40320-5_1."},{"pmid":"36648882","type":"BACKGROUND","citation":"Plano F, Corsale AM, Gigliotta E, Camarda G, Vullo C, Di Simone M, Shekarkar Azgomi M, Speciale M, Carlisi M, Caccamo N, Dieli F, Meraviglia S, Siragusa S, Botta C. Monoclonal Gammopathies and the Bone Marrow Microenvironment: From Bench to Bedside and Then Back Again. Hematol Rep. 2023 Jan 9;15(1):23-49. doi: 10.3390/hematolrep15010004."},{"pmid":"33498356","type":"BACKGROUND","citation":"Padala SA, Barsouk A, Barsouk A, Rawla P, Vakiti A, Kolhe R, Kota V, Ajebo GH. Epidemiology, Staging, and Management of Multiple Myeloma. Med Sci (Basel). 2021 Jan 20;9(1):3. doi: 10.3390/medsci9010003."},{"type":"BACKGROUND","citation":"Cancer.Org. Published 2012. Https://Www.Cancer.Org/Cancer/Multiple-Myeloma/Detectiondiagnosis-Staging/Surviva l-Rates.Html. Accessed January 19, 2023."},{"type":"BACKGROUND","citation":"Multiple Myeloma - Statistics. Cancer.Net. Published February 28, 2019. Https://Www.Cancer.Net/Cancer-Types/Multiple-Myeloma/Statistics. Accessed January 19, 2023."},{"pmid":"17582068","type":"BACKGROUND","citation":"Kyle RA, Remst