* Any ocular lesion arising from ophthalmic vascular disease, such as partial or complete loss of vision or defect in visual fields.
* Smokes.","healthyVolunteers":true,"sex":"FEMALE","minimumAge":"18 Years","maximumAge":"35 Years","stdAges":["ADULT"]},"contactsLocationsModule":{"overallOfficials":[{"name":"Roger A Pierson, PhD","affiliation":"University of Saskatchewan","role":"PRINCIPAL_INVESTIGATOR"},{"name":"Donna R Chizen, MD","affiliation":"University of Saskatchewan","role":"PRINCIPAL_INVESTIGATOR"}],"locations":[{"facility":"Royal University Hospital","city":"Saskatoon","state":"Saskatchewan","zip":"S7N 0W8","country":"Canada","geoPoint":{"lat":52.13238,"lon":-106.66892}}]},"referencesModule":{"references":[{"pmid":"28107821","type":"DERIVED","citation":"Allaway HC, Chizen DR, Adams GP, Pierson RA. Effects of a single 20 mg dose of letrozole on ovarian function post dominant follicle selection: an exploratory randomized controlled trial. J Ovarian Res. 2017 Jan 21;10(1):6. doi: 10.1186/s13048-017-0303-x."}]}},"derivedSection":{"miscInfoModule":{"versionHolder":"2026-09-21"},"interventionBrowseModule":{"meshes":[{"id":"D000077289","term":"Letrozole"}],"ancestors":[{"id":"D009570","term":"Nitriles"},{"id":"D009930","term":"Organic Chemicals"},{"id":"D014230","term":"Triazoles"},{"id":"D001393","term":"Azoles"},{"id":"D006573","term":"Heterocyclic Compounds, 1-Ring"},{"id":"D006571","term":"Heterocyclic Compounds"}]}},"hasResults":false},
