{"protocolSection":{"identificationModule":{"nctId":"NCT04418635","orgStudyIdInfo":{"id":"LPO201910"},"organization":{"fullName":"Acrobio Healthcare Inc.","class":"INDUSTRY"},"briefTitle":"Herbal Supplement Prosta-OK® Neo as an Adjunct Therapy in Patients With Mild to Severe Non-neurogenic Male Lower Urinary Tract Symptoms Receiving Tamsulosin Therapy","officialTitle":"Herbal Supplement Prosta-OK® Neo as an Adjunct Therapy in Patients With Mild to Severe Non-neurogenic Male Lower Urinary Tract Symptoms Receiving Tamsulosin Therapy: a Double-blind, Randomized, Placebo-controlled Trial."},"statusModule":{"statusVerifiedDate":"2020-05","overallStatus":"UNKNOWN","lastKnownStatus":"RECRUITING","expandedAccessInfo":{"hasExpandedAccess":false},"startDateStruct":{"date":"2020-06-04","type":"ESTIMATED"},"primaryCompletionDateStruct":{"date":"2021-12-31","type":"ESTIMATED"},"completionDateStruct":{"date":"2021-12-31","type":"ESTIMATED"},"studyFirstSubmitDate":"2020-05-18","studyFirstSubmitQcDate":"2020-06-03","studyFirstPostDateStruct":{"date":"2020-06-05","type":"ACTUAL"},"lastUpdateSubmitDate":"2020-06-03","lastUpdatePostDateStruct":{"date":"2020-06-05","type":"ACTUAL"}},"sponsorCollaboratorsModule":{"responsibleParty":{"type":"SPONSOR"},"leadSponsor":{"name":"Acrobio Healthcare Inc.","class":"INDUSTRY"}},"oversightModule":{"oversightHasDmc":false,"isFdaRegulatedDrug":false,"isFdaRegulatedDevice":false},"descriptionModule":{"briefSummary":"The aim of the study is to uses Prosta-OK® Neo that contains herb extracts including lycopene, phellinus linteus, pomegranate, pumpkin seed, selenium and zinc that have been demonstrated with functions of inhibiting 5-alpha reductase, antioxidant, anti-inflammation and regulating the synthesis of nitric oxide to explore whether Prosta-OK® can help reduce symptoms and elevate the quality of life in patients with mild to severe non-neurogenic male lower urinary tract symptoms receiving Tamsulosin therapy.","detailedDescription":"Lower urinary tract symptoms (LUTS) are kind of uncomfortable subjective feelings reported from patients and are divided into three groups, storage, voiding, and postmicturition symptoms. Many epidemiological studies have pointed out that the prevalence of LUTS among individuals aged at least 40 years in the United States, the United Kingdom, Sweden, China, Taiwan, and South Korea is up to 60%. LUTS may cause mental health disorders such as anxiety and depression and affect lifestyle that leads to a negative impact on the quality of life. In recent years, there have been numerous academic or clinical studies that assess the improvement of plant and herb extracts in LUTS.

Prosta-OK® Neo is mainly comprised of herb extracts, including lycopene, phellinus linteus, pomegranate, pumpkin seed, selenium and zinc that have been demonstrated with functions of inhibiting 5-alpha reductase, antioxidant, anti-inflammation and regulating the synthesis of nitric oxide.

The aim of the study is to explore whether take Prosta-OK® 2 tablets for 85 days compared with placebo group can help reduce symptoms and elevate the quality of life in patients with mild to severe non-neurogenic male LUTS receiving Tamsulosin therapy."},"conditionsModule":{"conditions":["Lower Urinary Tract Symptoms"],"keywords":["lower urinary tract symptoms","International Prostate Symptom Score","tamsulosin","adjunct therapy","herbal extractions","double-blind","randomized controlled trial"]},"designModule":{"studyType":"INTERVENTIONAL","phases":["NA"],"designInfo":{"allocation":"RANDOMIZED","interventionModel":"PARALLEL","primaryPurpose":"SUPPORTIVE_CARE","maskingInfo":{"masking":"QUADRUPLE","whoMasked":["PARTICIPANT","CARE_PROVIDER","INVESTIGATOR","OUTCOMES_ASSESSOR"]}},"enrollmentInfo":{"count":100,"type":"ESTIMATED"}},"armsInterventionsModule":{"armGroups":[{"label":"Tamsulosin and Prosta-OK® Neo","type":"EXPERIMENTAL","description":"Tamsulosin 0.2mg once daily and Prosta-OK® Neo 707mg 2 tablets twice daily for 85 days","interventionNames":["Dietary Supplement: Prosta-OK® Neo or Prosta-OK® Neo-matched placebo"]},{"label":"Tamsulosin and Prosta-OK® Neo-matched placebo","type":"PLACEBO_COMPARATOR","description":"Tamsulosin 0.2mg once daily and Prosta-OK® Neo-matched placebo 707mg 2 tablets twice daily for 85 days","interventionNames":["Dietary Supplement: Prosta-OK® Neo or Prosta-OK® Neo-matched placebo"]}],"interventions":[{"type":"DIETARY_SUPPLEMENT","name":"Prosta-OK® Neo or Prosta-OK® Neo-matched placebo","description":"the patient planed to receive Tamsulosin 0.2mg once daily is randomized to the experiment group or placebo group. After randomization, the patient received Tamsulosin therapy with Prosta-OK® Neo or Prosta-OK® Neo-matched placebo 707mg 2 tablets twice daily for 85 days.","armGroupLabels":["Tamsulosin and Prosta-OK® Neo","Tamsulosin and Prosta-OK® Neo-matched placebo"]}]},"outcomesModule":{"primaryOutcomes":[{"measure":"change in International Prostate Symptom Score from baseline on the sum of 1 to 7 questions","description":"compare the change in International Prostate Symptom Score from baseline between the experiment group and placebo group on the sum of 1 to 7 questions that are related to voiding symptoms. Scores of 0 to 7, 8 to 19, and 20 to 35 signify mild, moderate, and severe symptoms, respectively.","timeFrame":"day 1 (before receiving therapy) and day 85"}],"secondaryOutcomes":[{"measure":"change in International Prostate Symptom Score on questions 1, 3, and 5 that are related to voiding symptoms, questions 2, 4, and 7 that are related to storage symptoms, and question 8 that is related to the quality of life from baseline","description":"compare the change in International Prostate Symptom Score on questions 1, 3, and 5 that are related to voiding symptoms, questions 2, 4, and 7 that are related to storage symptoms, and question 8 that is related to the quality of life from baseline between the experiment group and placebo group. A higher score is indicated more severe in symptoms.","timeFrame":"day 1 (before receiving therapy) and day 85"},{"measure":"change in International Prostate Symptom Score from baseline by visit on the sum of 1 to 7 questions that are related to voiding symptoms and question 8 that is related to the quality of life","description":"compare the change in International Prostate Symptom Score from baseline by visit between the experiment group and placebo group on the sum of 1 to 7 questions that are related to voiding symptoms and question 8 that is related to the quality of life. A higher score is indicated more severe in symptoms or dissatisfaction in the quality of life.","timeFrame":"day 1 (before receiving therapy), day 15, day 29, and day 85"},{"measure":"change in interleukin 6, interleukin 8, tumor necrosis factor-alpha and interleukin 1 beta levels in expressed prostatic secretion from baseline by visit","description":"compare the change in interleukin 6, interleukin 8, tumor necrosis factor-alpha and interleukin 1 beta levels in expressed prostatic secretion collected from urine after a prostate massage from baseline by visit between the experiment group and placebo group.","timeFrame":"day 1 (before receiving therapy), day 15, day 29, and day 85"},{"measure":"change in maximum urinary flow rate from baseline.","description":"compare change in maximum urinary flow rate from baseline between the experiment group and placebo group.","timeFrame":"day 1 (before receiving therapy) and day 85"},{"measure":"change in amount of post voiding residual urine from baseline.","description":"compare change in amount of post voiding residual urine from baseline between the experiment group and placebo group.","timeFrame":"day 1 (before receiving therapy) and day 85"},{"measure":"percentage of patients with adverse reaction","description":"adverse reactions caused by the investigational product will be documented and recorded for analysis.","timeFrame":"day 1 (after receiving therapy) to day 85"},{"measure":"correlation of lifestyle factors on the severity of non-neurogenic male lower urinary tract symptoms assessed by the International Prostate Symptom Score","description":"Lifestyle factors are assessed by self-designed questionnaires. The severity of non-neurogenic male lower urinary tract symptoms is assessed by the International Prostate Symptom Score, consisting of 8 questions, of which 1 to 7 questions are for evaluating the symptoms of voiding and question 8 is for evaluating the quality of life. A higher score is indicated more severe in symptoms or dissatisfaction in the quality of life.","timeFrame":"screening visit to day 85"},{"measure":"correlation of the other external factors on the severity of non-neurogenic male lower urinary tract symptoms assessed by the International Prostate Symptom Score","description":"The other external factors are assessed by self-designed questionnaires. The severity of non-neurogenic male lower urinary tract symptoms is assessed by the International Prostate Symptom Score, consisting of 8 questions, of which 1 to 7 questions are for evaluating the symptoms of voiding and question 8 is for evaluating the quality of life. A higher score is indicated more severe in symptoms or dissatisfaction in the quality of life.","timeFrame":"screening visit to day 85"}]},"eligibilityModule":{"eligibilityCriteria":"Inclusion Criteria:

* male between the ages of 30 and 55 when signing the informed consent form
* the subject was diagnosed with mild to severe non-neurogenic lower urinary tract symptoms and planed to receive Tamsulosin therapy
* the sum of International Prostate Symptom Score (IPSS) on questions 1 to 7 was 10 points or higher
* the subject can take medication via oral or nasogastric tube confirmed with the function of absorption by the principal investigator or co-principal investigators
* the subject was willing to corporate study-related procedures and sign the informed consent form

Exclusion Criteria:

* post-void residual urine volume greater than 200 mL or peak of maximum urine flow rate less than 5 mL/s
* total serum prostate-specific antigen higher than 10 ng/mL
* bladder outlet obstruction caused by reasons other than benign prostatic hyperplasia
* lower urinary tract symptoms caused by neurological disease such as Cerebrovascular Diseases, Parkinson's, dementia, Multiple Sclerosis (MS), spinal cord injuries (SCI), cauda equina syndrome, and Peripheral Neuropathy
* history or evidence of prostate cancer, male reproductive cancers, bladder cancer, and cancer of the ureter and urethra
* history or evidence of acute urinary retention (AUR)
* history or evidence of acute orthostatic hypotension
* with the urinary catheter or intermittent catheter
* stone in the urinary system
* Interstitial cystitis (IC), neurogenic bladder, overactive bladder (OAB) and Inflammatory Bowel Disease (IBD) within 3 mo prior to study entry
* chemotherapy or radiation therapy within 3 mo prior to study entry
* immunosuppressive therapy within 2 mo prior to study entry
* pelvic surgery or urinary surgery within 2 mo prior to study entry
* 5-alpha-reductase inhibitors use within 6 mo prior to entry or alpha-1-adrenergic blockers use within 2 w prior to entry
* the subject plans to use medication other than Tamsulosin such as alpha-blocker, 5-alpha-reductase inhibitors, antimuscarinic drugs, phosphodiesterase type 5 inhibitor (PDE5 inhibitors), Beta-3 agonists, desmopressin, diuretics, phenazopyridine, other drugs or foods are known to interact with tamsulosin and steroid or a nonsteroidal anti-inflammatory drug during participating in the study.
* the subject plans to receive cataract surgery during participating in the study or 1 mo after participating in the study.
* the subject took other therapies such as acupuncture or phytotherapy, including Saw Palmetto, Pygeum Africanum, Hypoxis Rooperi, Rye-pollen extract, and Pumpkin Seed extract within 2 w prior to entry.
* the subject took Chinese herbs such as Soaring Dragon Decoction, Rehmannia Right Formula, Powder for Five Types of Painful Urinary Dysfunction, Minor Bupleurum Decoction, Artemisiae Scopariae Decoction, Decoction to Enrich Yin and Direct Fire Downward, Tonifies Qi、Coptis Decoction to Relieve Toxicity and related modifications, Radix Rehmanniae, Cortex Moutan, Radix Pulsatillae, Herba Taraxaci, Herba Portulacae, Fructus Forsythiae, Flos Lonicerae, Herba Lophatheri, Fructus Gardeniae, Phellinus linteus within 7 days prior to entry.
* have a history of allergy to the ingredients of investigational product
* Serum Glutamic-Oxaloacetic Transaminase and serum Glutamic-Pyruvic Transaminase were more than three times of normal range or Serum creatinine less than 1.5 mg/dL
* have a history of substance abuse within 2 yr prior to entry
* participating in any clinical trial such as health food, herbal extracts, and drug within 30 days prior to entry
* have other significant diseases and confirmed by the principal investigator as non-eligible to be enrolled in the study","healthyVolunteers":false,"sex":"MALE","minimumAge":"30 Years","maximumAge":"55 Years","stdAges":["ADULT"]},"contactsLocationsModule":{"centralContacts":[{"name":"Clinical Research Associate","role":"CONTACT","phone":"+886-2-2249-1998","phoneExt":"252","email":"acrobio64@acrobio.com.tw"},{"name":"Pharmacist","role":"CONTACT","phone":"+886-2-2249-1998","phoneExt":"254","email":"acrobio23@acrobio.com.tw"}],"overallOfficials":[{"name":"Dong-Ru HO, MD","affiliation":"Chang Gung Memorial Hospital","role":"PRINCIPAL_INVESTIGATOR"}],"locations":[{"facility":"Chiayi Chang Gung Memorial Hospital","status":"RECRUITING","city":"Chiayi County","zip":"613016","country":"Taiwan","contacts":[{"name":"Study principal investigator","role":"CONTACT","phone":"+886-5-3621-000","phoneExt":"3191","email":"redoxdrh@gmail.com"}]}]},"ipdSharingStatementModule":{"ipdSharing":"UNDECIDED"}},"derivedSection":{"miscInfoModule":{"versionHolder":"2026-09-21"},"conditionBrowseModule":{"meshes":[{"id":"D059411","term":"Lower Urinary Tract Symptoms"}],"ancestors":[{"id":"D020924","term":"Urological Manifestations"},{"id":"D012816","term":"Signs and Symptoms"},{"id":"D013568","term":"Pathological Conditions, Signs and Symptoms"}]}},"hasResults":false},
