ases"},{"id":"D009140","term":"Musculoskeletal Diseases"},{"id":"D012216","term":"Rheumatic Diseases"},{"id":"D003240","term":"Connective Tissue Diseases"},{"id":"D017437","term":"Skin and Connective Tissue Diseases"},{"id":"D001327","term":"Autoimmune Diseases"},{"id":"D007154","term":"Immune System Diseases"}]},"interventionBrowseModule":{"meshes":[{"id":"C584571","term":"GLPG0634"},{"id":"D004364","term":"Pharmaceutical Preparations"},{"id":"D000068879","term":"Adalimumab"},{"id":"D000068800","term":"Etanercept"}],"ancestors":[{"id":"D061067","term":"Antibodies, Monoclonal, Humanized"},{"id":"D000911","term":"Antibodies, Monoclonal"},{"id":"D000906","term":"Antibodies"},{"id":"D007136","term":"Immunoglobulins"},{"id":"D007162","term":"Immunoproteins"},{"id":"D001798","term":"Blood Proteins"},{"id":"D011506","term":"Proteins"},{"id":"D000602","term":"Amino Acids, Peptides, and Proteins"},{"id":"D012712","term":"Serum Globulins"},{"id":"D005916","term":"Globulins"},{"id":"D007141","term":"Immunoglobulin Fc Fragments"},{"id":"D007128","term":"Immunoglobulin Fragments"},{"id":"D010446","term":"Peptide Fragments"},{"id":"D010455","term":"Peptides"},{"id":"D007127","term":"Immunoglobulin Constant Regions"},{"id":"D018124","term":"Receptors, Tumor Necrosis Factor"},{"id":"D018121","term":"Receptors, Cytokine"},{"id":"D011971","term":"Receptors, Immunologic"},{"id":"D011956","term":"Receptors, Cell Surface"},{"id":"D008565","term":"Membrane Proteins"}]}},"hasResults":false},
{"protocolSection":{"identificationModule":{"nctId":"NCT07187635","orgStudyIdInfo":{"id":"Truce-LB01"},"organization":{"fullName":"Tianjin Medical University Second Hospital","class":"OTHER"},"briefTitle":"Guiding Value of Urinary Tumor DNA Testing in Repeat Transurethral Resection of Non-Muscle-Invasive Bladder Cancer","officialTitle":"The Guiding Value of Urinary Tumor DNA Testing in Repeat Transurethral Resection of Non-Muscle-Invasive Bladder Cancer: An Open-Label, Randomized Controlled, Multi-Center Clinical Study (Truce-LB01)"},"statusModule":{"statusVerifiedDate":"2026-08","overallStatus":"RECRUITING","expandedAccessInfo":{"hasExpandedAccess":false},"startDateStruct":{"date":"2025-09-28","type":"ACTUAL"},"primaryCompletionDateStruct":{"date":"2027-10-01","type":"ESTIMATED"},"completionDateStruct":{"date":"2027-11-01","type":"ESTIMATED"},"studyFirstSubmitDate":"2025-09-11","studyFirstSubmitQcDate":"2025-09-20","studyFirstPostDateStruct":{"date":"2025-09-23","type":"ACTUAL"},"lastUpdateSubmitDate":"2026-08-13","lastUpdatePostDateStruct":{"date":"2026-08-14","type":"ACTUAL"}},"sponsorCollaboratorsModule":{"responsibleParty":{"type":"SPONSOR"},"leadSponsor":{"name":"Tianjin Medical University Second Hospital","class":"OTHER"}},"oversightModule":{"oversightHasDmc":true,"isFdaRegulatedDrug":false,"isFdaRegulatedDevice":false},"descriptionModule":{"briefSummary":"Non-muscle-invasive bladder cancer (NMIBC) accounts for approximately 75% of newly diagnosed bladder cancers and is characterized by a high risk of recurrence and progression. Current guidelines recommend that patients with stage T1 NMIBC undergo a second transurethral resection of bladder tumor (re-TURBT) within 2-6 weeks after the initial surgery to remove residual tumor, confirm staging, and obtain additional pathological information. However, the benefits of routine re-TURBT for all high-risk patients remain controversial, as many patients may not have residual disease, while the procedure carries surgical and anesthetic risks, physical and psychological burden, and additional healthcare costs.

Urine tumor DNA (utDNA) refers to DNA fragments shed by tumor cells into urine. It can be detected using molecular assays with high sensitivity and specificity, offering a non-invasive method for bladder cancer diagnosis and surveillance. Previous studies have shown that positive utDNA results after initial TURBT may be associated with residual disease and higher recurrence risk.

This multicenter, randomized controlled trial aims to evaluate whether utDNA testing can accurately identify NMIBC patients who are most likely to benefit from re-TURBT, thereby guiding the decision to perform the procedure. The goal is to optimize patient selection for re-TURBT, reduce unnecessary surgeries, and improve patient quality of life while maintaining oncologic safety."},"conditionsModule":{"conditions":["Bladder Cancer","Liquid Biopsy","Repeat Transurethral Resection of Bladder Tumor"],"keywords":["bladder cancer","liquid biopsy","second transurethral resection of bladder tumor"]},"designModule":{"studyType":"INTERVENTIONAL","phases":["NA"],"designInfo":{"allocation":"RANDOMIZED","interventionModel":"PARALLEL","primaryPurpose":"TREATMENT","maskingInfo":{"masking":"NONE"}},"enrollmentInfo":{"count":196,"type":"ESTIMATED"}},"armsInterventionsModule":{"armGroups":[{"label":"Standard re-TURBT","type":"ACTIVE_COMPARATOR","description":"Participants with NMIBC who have undergone initial TURBT will not receive utDNA testing and will undergo a second transurethral resection of bladder tumor (re-TURBT) within 2-6 weeks after the initial surgery, per guideline-based management.","interventionNames":["Procedure: Second Transurethral Resection of Bladder Tumor (re-TURBT)"]},{"label":"utDNA-guided management","type":"EXPERIMENTAL","description":"Participants with NMIBC who have undergone initial TURBT will receive urine tumor DNA (utDNA) testing.

If utDNA positive, they will undergo re-TURBT within 2-6 weeks after the initial surgery.

If utDNA negative, re-TURBT will be omitted and patients will continue guideline-based adjuvant therapy/surveillance as per protocol.","interventionNames":["Diagnostic Test: utDNA Testing (Urine Tumor DNA Detection)"]}],"interventions":[{"type":"PROCEDURE","name":"Second Transurethral Resection of Bladder Tumor (re-TURBT)","description":"Participants with NMIBC who have undergone initial TURBT will not receive utDNA testing and will undergo a second transurethral resection of bladder tumor (re-TURBT) within 2-6 weeks after the initial surgery, in accordance with current clinical guidelines.","armGroupLabels":["Standard re-TURBT"]},{"type":"DIAGNOSTIC_TEST","name":"utDNA Testing (Urine Tumor DNA Detection)","description":"Participants with NMIBC who have undergone initial TURBT will receive urine tumor DNA (utDNA) testing.

If utDNA is positive, the patient will undergo a second transurethral resection of bladder tumor (re-TURBT) within 2-6 weeks after the initial surgery.

If utDNA is negative, re-TURBT will be omitted and patients will proceed to guideline-based adjuvant therapy or surveillance.","armGroupLabels":["utDNA-guided management"]}]},"outcomesModule":{"primaryOutcomes":[{"measure":"Recurrence-free survival (RFS)","description":"Time from randomization to the first documented event of bladder tumor recurrence (any grade), upper tract urothelial recurrence.","timeFrame":"Up to 24 months from randomization"}],"secondaryOutcomes":[{"measure":"Progression-free survival (PFS)","description":"Time from initial TURBT to disease progression (development of muscle-invasive bladder cancer, distant metastasis).","timeFrame":"Up to 24 months from randomization"},{"measure":"Pathological outcomes of second transurethral resection (re-TURBT)","description":"Proportion of patients with residual tumor, upstaging (higher T category at re-TURBT), or concomitant CIS among those undergoing repeat TURBT.","timeFrame":"Perioperative (day of repeat TURBT)"},{"measure":"Patient-reported outcomes","description":"Health outcomes directly reported by the patient without interpretation by clinicians or others. These measures capture patients' perceptions of symptoms, functional status, health-related quality of life (HRQoL), and treatment-related burden.","timeFrame":"Up to 24 months from randomization."}],"otherOutcomes":[{"measure":"Correlation Between utDNA Status and Clinical Outcomes","description":"Association of urine utDNA results with cystoscopy findings, imaging results, and re-TURBT pathology; evaluation of diagnostic performance (sensitivity, specificity, predictive values, AUC) and relation to recurrence/progression.","timeFrame":"Up to 24 months from randomization"}]},"eligibilityModule":{"eligibilityCriteria":"Inclusion Criteria:

Participants must meet all of the following criteria to be eligible for the study:

1. Male or female, aged 18 years or older.
2. Histologically confirmed non-muscle-invasive bladder tumor, with no evidence of muscle-invasive bladder cancer or metastatic disease.
3. Histologically confirmed urothelial carcinoma of the bladder or bladder tumor with urothelial carcinoma as the predominant component (\>50%).
4. At least one of the following conditions:

   1. Incomplete initial transurethral resection of bladder tumor (TURBT) or suspected incomplete resection.
   2. Absence of detrusor muscle in the initial TURBT pathological specimen (except for low-grade Ta stage tumors or carcinoma in situ \[CIS\]).
   3. T1 stage tumor.
5. Willingness to provide a 50 mL urine sample between 2-6 weeks after the initial TURBT and prior to re-TURBT.
6. Willingness to provide tumor tissue samples for pathological examination.
7. Willingness to undergo genetic testing required for the trial.

Exclusion Criteria:

1. Contraindications to transurethral resection of bladder tumor (TURBT).
