{"protocolSection":{"identificationModule":{"nctId":"NCT04002635","orgStudyIdInfo":{"id":"2019LEFT001"},"organization":{"fullName":"CRG UZ Brussel","class":"OTHER"},"briefTitle":"Letrozole for Frozen Embryo Transfer (FET) in Patients With Polycystic Ovary Syndrome (PCOS)","officialTitle":"Endometrial Preparation Using Letrozole Compared to Artificial Cycle for Frozen Embryo Transfer in PCOS Patients","acronym":"LEFT"},"statusModule":{"statusVerifiedDate":"2021-01","overallStatus":"WITHDRAWN","whyStopped":"Practical issues","expandedAccessInfo":{"hasExpandedAccess":false},"startDateStruct":{"date":"2020-12-01","type":"ESTIMATED"},"primaryCompletionDateStruct":{"date":"2021-04-01","type":"ESTIMATED"},"completionDateStruct":{"date":"2022-04-01","type":"ESTIMATED"},"studyFirstSubmitDate":"2019-06-27","studyFirstSubmitQcDate":"2019-06-27","studyFirstPostDateStruct":{"date":"2019-06-28","type":"ACTUAL"},"lastUpdateSubmitDate":"2021-01-06","lastUpdatePostDateStruct":{"date":"2021-01-08","type":"ACTUAL"}},"sponsorCollaboratorsModule":{"responsibleParty":{"type":"PRINCIPAL_INVESTIGATOR","investigatorFullName":"Liese Boudry","investigatorTitle":"Medical doctor","investigatorAffiliation":"CRG UZ Brussel"},"leadSponsor":{"name":"CRG UZ Brussel","class":"OTHER"},"collaborators":[{"name":"University Hospital, Ghent","class":"OTHER"}]},"oversightModule":{"oversightHasDmc":true,"isFdaRegulatedDrug":false,"isFdaRegulatedDevice":false,"isUsExport":false},"descriptionModule":{"briefSummary":"To offer patients with oligomenorrhoea or amenorrhoea an alternative to frozen embryo transfer in an artificial cycle, endometrial preparation using letrozole may be a valuable option. Letrozole, a potent, reversible nonsteroidal aromatase inhibitor with relatively short half-life, can successfully induce ovulation without any adverse anti-estrogenic effects and thus without affecting the endometrium. The use of letrozole typically results in monofollicular growth and this reduces the effect of supraphysiological levels of estrogen on the endometrium and embryo. The purpose of this study is to compare a frozen-thawed embryo transfer in an artificial cycle with a letrozole-induced ovulatory cycle, specifically in PCOS patients. The primary outcome is early pregnancy loss."},"conditionsModule":{"conditions":["Infertility, Female","Polycystic Ovary Syndrome","IVF","Ovulation Disorder"],"keywords":["frozen embryo transfer"]},"designModule":{"studyType":"INTERVENTIONAL","phases":["PHASE4"],"designInfo":{"allocation":"RANDOMIZED","interventionModel":"PARALLEL","primaryPurpose":"TREATMENT","maskingInfo":{"masking":"NONE"}},"enrollmentInfo":{"count":0,"type":"ACTUAL"}},"armsInterventionsModule":{"armGroups":[{"label":"Hormonal Replacement Therapy","type":"ACTIVE_COMPARATOR","description":"Artificial preparation of the endometrium using estradiol valerate 2mg 3x/day, and vaginal micronized progesterone 2x 400mg/day.","interventionNames":["Drug: estradiol valerate"]},{"label":"Letrozole","type":"EXPERIMENTAL","description":"Using letrozole for ovulation induction before planning the frozen embryo transfer","interventionNames":["Drug: Letrozole"]}],"interventions":[{"type":"DRUG","name":"Letrozole","description":"Letrozole ovulation induction","armGroupLabels":["Letrozole"]},{"type":"DRUG","name":"estradiol valerate","description":"hormonal replacement therapy","armGroupLabels":["Hormonal Replacement Therapy"],"otherNames":["progesterone"]}]},"outcomesModule":{"primaryOutcomes":[{"measure":"early pregnancy loss","timeFrame":"12 weeks after frozen embryo transfer"}],"secondaryOutcomes":[{"measure":"cancellation rate","timeFrame":"2 months"},{"measure":"number of visits to the clinic","timeFrame":"2 months"},{"measure":"endometrial thickness on the day of planning of FET","timeFrame":"1 day"},{"measure":"implantation rate","timeFrame":"1 day"},{"measure":"biochemical and clinical pregnancy rate","timeFrame":"12 weeks"},{"measure":"live birth rate","timeFrame":"1 year"},{